typedef int __v4si __attribute__((__vector_size__(16)));
__m128 x1, x2, x3, x4;
struct Container {
  __m128 f;
};
class fVec {
public:
  Container mData;
  fVec(const __m128 &);
  fVec operator-() const;
};
void consume(fVec);
fVec::fVec(const __m128 &m) { mData.f = m; }
fVec fVec::operator-() const {
  __m128 k = -mData.f;
  return k;
