```cpp
/// This function preserves the caller's attribute if it is set, 
/// and does not change it based on the callee's attribute.
template<typename AttrClass>
static void retainCallerAttribute(Function &Caller, const Function &Callee) {
  // If the attribute is set on the caller, keep it.
  if (AttrClass::isSet(Caller, AttrClass::getKind())) {
    return;
  }
  
  // The callee's attributes do not influence the caller's attributes,
  // no further action.
}
