issue_body:
Clang at -Os produced the wrong code.

Bisected to 6ed152aff4aab6307ecaab64a544d0524ea5f50e, which was committed by @caojoshua 

Compiler explorer: https://godbolt.org/z/aMEWqd9dP

```console
% cat a.c
int printf(const char *, ...);
int a, b, c;
long d;
const unsigned *e;
const unsigned **f[3];
static char(g)(unsigned h, int j) { return h > j ? h : h << j; }
static short k() {
  char l = 1;
  b = 0;
  for (; b <= 3; b++) {
    char *m = &l;
    int *n = &c;
    int i = 0;
    for (; i < 3; i++)
      f[i] = &e;
    *n = g((*m)--, 7);
    if (*n)
      ;
    else {
      for (; i < 9; i++)
        f[0] || (d = 2);
      if (0 < *n)
        ;
      else
        return 0;
    }
    printf("%d\n", *n);
  }
  return 1;
}
int main() {
  k();
}
%
% clang -O0 a.c && ./a.out
-128
0
% clang -Os a.c && ./a.out
-128
0
-128
0
%
```

issue_comment:
Simplified, and failing on all optimization levels other than `-O0`:
```c
int printf(const char *, ...);
int main() {
  unsigned char l = 1;
  for (unsigned char b = 0; b <= 3; b++) {
    unsigned char c = l << 7;
    l--;
    if (c == 0) {
        return 0;
    }
    printf("%d\n", c);
  }
}
```
https://godbolt.org/z/eeWMWajnb (also works with any integer type & accordingly adjusted shift such that it shifts LSB to MSB)

